import argparse
import math
import sys


def ploidy_cutoff(path):
    with open(path) as stream:
        for line in stream:
            fields = line.split()
            if fields and fields[0] == "noise-trough":
                # Round the continuous trough to the nearest integer; callers
                # retain k-mers with multiplicity strictly above it.
                return int(math.floor(float(fields[1]) + 0.5))
    raise ValueError(f"No noise-trough record found in {path}")


def read_counts(path):
    result = {}
    with open(path) as stream:
        header = stream.readline().rstrip().split("\t")
        for line in stream:
            fields = line.rstrip().split("\t")
            if fields and fields[0]:
                result[fields[0]] = dict(zip(header[1:], map(int, fields[1:])))
    return result


def imbalance(counts):
    """Express parental imbalance as the larger-to-smaller marker ratio."""
    low = min(counts["maternal"], counts["paternal"])
    high = max(counts["maternal"], counts["paternal"])
    return float("inf") if low == 0 else high / low


def main():
    parser = argparse.ArgumentParser(
        description="Select Merqury-compatible solid k-mer cutoffs and assess parental marker balance"
    )
    parser.add_argument("--child-ploidy")
    parser.add_argument("--maternal-ploidy")
    parser.add_argument("--paternal-ploidy")
    parser.add_argument(
        "--marker-counts",
        help="TSV with candidate, maternal and paternal marker counts for auto and cutoff2",
    )
    parser.add_argument("--max-marker-ratio", type=float, default=2.0)
    parser.add_argument("--max-cutoff-ratio", type=float, default=2.0)
    parser.add_argument("--max-cutoff-difference", type=int, default=3)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()

    cutoffs = {}
    if args.child_ploidy:
        cutoffs["child"] = ploidy_cutoff(args.child_ploidy)
    if args.maternal_ploidy:
        cutoffs["maternal"] = ploidy_cutoff(args.maternal_ploidy)
    if args.paternal_ploidy:
        cutoffs["paternal"] = ploidy_cutoff(args.paternal_ploidy)

    warnings = []
    parent_cutoffs = [cutoffs[x] for x in ("maternal", "paternal") if x in cutoffs]
    cutoffs_differ = False
    if len(parent_cutoffs) == 2:
        low_cutoff = min(parent_cutoffs)
        high_cutoff = max(parent_cutoffs)
        cutoffs_differ = (
            high_cutoff - low_cutoff >= args.max_cutoff_difference
            or (low_cutoff == 0 and high_cutoff > 0)
            or (low_cutoff > 0 and high_cutoff / low_cutoff >= args.max_cutoff_ratio)
        )
        if cutoffs_differ:
            warnings.append("parental solid k-mer cutoffs differ substantially")

    # Cutoff 2 is deliberately a guarded fallback, not an unconditional
    # override: it must improve balance without discarding most markers from
    # the weaker parent.
    selected = "auto"
    counts = read_counts(args.marker_counts) if args.marker_counts else {}
    if "auto" in counts and "maternal" in counts["auto"] and "paternal" in counts["auto"]:
        auto_ratio = imbalance(counts["auto"])
        marker_imbalance = auto_ratio > args.max_marker_ratio
        if marker_imbalance:
            warnings.append(f"automatic parental marker counts are imbalanced ({auto_ratio:.3f}:1)")
        if (cutoffs_differ or marker_imbalance) and "cutoff2" in counts:
            fallback_ratio = imbalance(counts["cutoff2"])
            auto_min = min(counts["auto"]["maternal"], counts["auto"]["paternal"])
            fallback_min = min(counts["cutoff2"]["maternal"], counts["cutoff2"]["paternal"])
            if fallback_ratio < auto_ratio and fallback_min >= max(1, auto_min // 2):
                selected = "cutoff2"
                warnings.append(
                    f"using cutoff 2 because marker balance improves to {fallback_ratio:.3f}:1"
                )
            else:
                warnings.append("cutoff 2 did not improve balance without excessive marker loss")

    with open(args.output, "w") as output:
        output.write("database\tauto_cutoff\tselected_cutoff\n")
        for name, cutoff in cutoffs.items():
            output.write(f"{name}\t{cutoff}\t{2 if selected == 'cutoff2' else cutoff}\n")
        output.write(f"selection\t{selected}\t{selected}\n")
        for warning in warnings:
            output.write(f"warning\t.\t{warning}\n")
            print(f"WARNING: {warning}", file=sys.stderr)


if __name__ == "__main__":
    main()
